INSERT INTO DEDUCTION_TYPE (
    TYPE_ID, TAX_YEAR, TYPE_CODE, TYPE_NAME, DEDUCTION_KIND,
    RATE, LIMIT_AMOUNT, SALARY_MIN, SALARY_MAX,
    CATEGORY_ID, PAY_METHOD, SOURCE_NOTE, UPDATED_AT, UPDATED_BY
) VALUES (
    SEQ_DEDUCTION_TYPE.NEXTVAL, #{dto.taxYear}, #{dto.code}, #{dto.name}, #{dto.deductionKind},
    #{dto.rate}, #{dto.limitAmount, jdbcType=NUMERIC}, #{dto.salaryMin}, #{dto.salaryMax, jdbcType=NUMERIC},
    #{dto.categoryId, jdbcType=NUMERIC}, #{dto.payMethod, jdbcType=VARCHAR}, #{dto.sourceNote}, SYSDATE, #{updatedBy}
)

INSERT INTO TAX_BRACKET (
    BRACKET_ID, TAX_YEAR, BRACKET_TYPE, LOWER_AMOUNT, UPPER_AMOUNT,
    RATE, BASE_AMOUNT, SOURCE_NOTE, UPDATED_AT, UPDATED_BY
) VALUES (
    SEQ_TAX_BRACKET.NEXTVAL, #{dto.taxYear}, #{dto.code}, #{dto.lowerAmount}, #{dto.upperAmount, jdbcType=NUMERIC},
    #{dto.rate}, #{dto.baseAmount}, #{dto.sourceNote}, SYSDATE, #{updatedBy}
)

INSERT INTO TAX_BRACKET (
    BRACKET_ID, TAX_YEAR, BRACKET_TYPE, LOWER_AMOUNT, UPPER_AMOUNT,
    RATE, BASE_AMOUNT, SOURCE_NOTE, UPDATED_AT, UPDATED_BY
)
SELECT
    SEQ_TAX_BRACKET.NEXTVAL, #{targetYear}, BRACKET_TYPE, LOWER_AMOUNT, UPPER_AMOUNT,
    RATE, BASE_AMOUNT, SOURCE_NOTE, SYSDATE, #{updatedBy}
FROM TAX_BRACKET
WHERE TAX_YEAR = #{sourceYear}
